input.command:
$scriptPath = "C:\Users\store\Downloads\rootmc-usb-tools\flash-ubuntu-f.ps1"
$logPath = "C:\Users\store\Downloads\rootmc-usb-tools\flash-ubuntu-f.log"
@'
# Flash Ubuntu Server hybrid ISO to SanDisk Cruzer Glide (Disk 3 / F:) via raw DD-style write.
$ErrorActionPreference = 'Stop'
$logPath = 'C:\Users\store\Downloads\rootmc-usb-tools\flash-ubuntu-f.log'
function Log($m) { $line = "[{0}] {1}" -f (Get-Date -Format o), $m; Add-Content -Path $logPath -Value $line; Write-Host $line }

try {
  '' | Set-Content -Path $logPath
  Log 'START flash-ubuntu-f'
  $isoPath = 'C:\Users\store\Downloads\ubuntu-26.04-live-server-amd64.iso'
  $expectedDisk = 3
  $expectedName = 'SanDisk Cruzer Glide'
  $expectedSerial = '04016804051724125459'
  $maxUsbBytes = 64GB

  if (-not ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    throw 'Not elevated — aborting'
  }
  if (-not (Test-Path $isoPath)) { throw "ISO missing: $isoPath" }
  $isoLen = (Get-Item $isoPath).Length
  Log ("ISO size bytes={0}" -f $isoLen)

  $disk = Get-Disk -Number $expectedDisk
  Log ("Disk {0}: Name={1} Bus={2} Size={3} Serial={4} IsBoot={5} IsSystem={6}" -f $disk.Number, $disk.FriendlyName, $disk.BusType, $disk.Size, $disk.SerialNumber, $disk.IsBoot, $disk.IsSystem)

  if ($disk.FriendlyName -ne $expectedName) { throw "Name mismatch: $($disk.FriendlyName)" }
  if ($disk.SerialNumber -ne $expectedSerial) { throw "Serial mismatch: $($disk.SerialNumber)" }
  if ($disk.BusType -ne 'USB') { throw "Not USB: $($disk.BusType)" }
  if ($disk.IsBoot -or $disk.IsSystem) { throw 'Disk is boot/system — abort' }
  if ($disk.Size -gt $maxUsbBytes) { throw "Disk too large ($($disk.Size)) — abort" }
  if ($disk.Size -lt $isoLen) { throw 'Disk smaller than ISO — abort' }

  # Refuse if any partition letters are C/D/E
  $parts = Get-Partition -DiskNumber $expectedDisk -ErrorAction SilentlyContinue
  foreach ($p in $parts) {
    if ($p.DriveLetter -in @('C','D','E')) { throw "Safety: partition letter $($p.DriveLetter) on target disk" }
    Log ("Partition {0} letter={1} size={2}" -f $p.PartitionNumber, $p.DriveLetter, $p.Size)
  }

  Log 'Clearing disk (Clean -RemoveData -Confirm:$false)'
  Clear-Disk -Number $expectedDisk -RemoveData -Confirm:$false -ErrorAction Stop

  # Dismount any residual volumes / take exclusive access
  Start-Sleep -Seconds 2
  Get-Disk -Number $expectedDisk | Get-Partition -ErrorAction SilentlyContinue | ForEach-Object {
    if ($_.DriveLetter) {
      $dl = "$($_.DriveLetter):"
      Log "Dismounting $dl"
      mountvol $dl /D 2>$null
    }
  }

  # Some Clear-Disk leave disk online with no partitions — good for raw write
  Set-Disk -Number $expectedDisk -IsReadOnly $false -ErrorAction SilentlyContinue

  $drivePath = "\\.\PhysicalDrive$expectedDisk"
  Log "Opening $drivePath for raw write"

  $bufferSize = 4MB
  $isoStream = [System.IO.File]::Open($isoPath, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::Read)
  try {
    # FILE_FLAG_WRITE_THROUGH via FileOptions.WriteThrough helps USB durability
    $diskStream = New-Object System.IO.FileStream($drivePath, [System.IO.FileMode]::Open, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::None, $bufferSize, [System.IO.FileOptions]::WriteThrough)
    try {
      $buffer = New-Object byte[] $bufferSize
      $written = [int64]0
      $total = $isoStream.Length
      $lastReport = [int64]0
      while (($read = $isoStream.Read($buffer, 0, $buffer.Length)) -gt 0) {
        $diskStream.Write($buffer, 0, $read)
        $written += $read
        if (($written - $lastReport) -ge 100MB) {
          Log ("Progress {0:N1} / {1:N1} MB ({2:P1})" -f ($written/1MB), ($total/1MB), ($written/$total))
          $lastReport = $written
        }
      }
      $diskStream.Flush()
      Log ("Write complete: {0} bytes" -f $written)
      if ($written -ne $total) { throw "Short write: $written != $total" }
    } finally {
      $diskStream.Dispose()
    }
  } finally {
    $isoStream.Dispose()
  }

  Log 'Rescanning disks'
  Update-HostStorageCache
  Start-Sleep -Seconds 3
  Get-Disk -Number $expectedDisk | Format-List Number, FriendlyName, PartitionStyle, Size, OperationalStatus | Out-String | ForEach-Object { Log $_.TrimEnd() }
  Get-Partition -DiskNumber $expectedDisk -ErrorAction SilentlyContinue | Format-Table PartitionNumber, DriveLetter, Size, Type -AutoSize | Out-String | ForEach-Object { Log $_.TrimEnd() }
  Get-Volume -ErrorAction SilentlyContinue | Where-Object { $_.DriveLetter } | Select-Object DriveLetter, FileSystemLabel, FileSystem, Size | Format-Table -AutoSize | Out-String | ForEach-Object { Log $_.TrimEnd() }

  Log 'SUCCESS'
} catch {
  Log ("FAIL: $($_.Exception.Message)")
  Log ($_ | Out-String)
  exit 1
}
'@ | Set-Content -Path $scriptPath -Encoding UTF8

Write-Host "Script written: $scriptPath"
# Elevate and run; wait for completion
$arg = "-NoProfile -ExecutionPolicy Bypass -File `"$scriptPath`""
$p = Start-Process -FilePath "powershell.exe" -ArgumentList $arg -Verb RunAs -PassThru -Wait
Write-Host "Elevated exit code: $($p.ExitCode)"
Write-Host "==== LOG ===="
if (Test-Path $logPath) { Get-Content $logPath } else { Write-Host "No log file yet (UAC denied?)" }
